  return { ...input, answer: { ok: true, verb, ref, value: value || '', by: input.contact_id, at: new Date(Number(input.now || Date.now())).toISOString() } }
};
const item = $input.item;
let input = { ...item.json };
const out = __fn(input);
return item.binary ? { json: out, binary: item.binary } : { json: out };

parameters.query:
update outbound set released_at = now()
where contact_id = $1 and held_body is not null and released_at is null and sent_at > now() - interval '7 days'
returning contact_id, mobilisation_id, kind, coalesce(area, '') as area, coalesce(line_code, '') as line_code, coalesce(ref, '') as ref, held_body as request;

insert into zones (mobilisation_id, area, name, shape, source)
select $1, o.area, o.area || ' (pin from contractor)', json_build_object('circle', json_build_object('lat', $2::float, 'lng', $3::float, 'radius_m', 30)), 'contractor_pin'
from outbound o where o.wamid = $4 and o.kind = 'area' returning id;

